-- 6. Faculty & Room Availability Allow-lists (All Slots Allowed)
INSERT INTO faculty_availability (id, institution_id, faculty_id, time_slot_id)
SELECT gen_random_uuid(), '22222222-2222-2222-2222-222222222222', f.id, ts.id
FROM faculty f CROSS JOIN time_slots ts
WHERE f.institution_id = '22222222-2222-2222-2222-222222222222'
ON CONFLICT (faculty_id, time_slot_id) DO NOTHING;

INSERT INTO room_availability (id, institution_id, room_id, time_slot_id)
SELECT gen_random_uuid(), '22222222-2222-2222-2222-222222222222', r.id, ts.id
FROM rooms r CROSS JOIN time_slots ts
WHERE r.institution_id = '22222222-2222-2222-2222-222222222222'
ON CONFLICT (room_id, time_slot_id) DO NOTHING;

